\[
x^2 - y^2 = (x + y)(x - y) = \left((2001^{1002} - 2001^{-1002}) + (2001^{1002} + 2001^{-1002})\right)\left((2001^{1002} - 2001^{-1002}) - (2001^{1002} + 2001^{-1002})\right)
\]
